solution.solution.cpp:
#include <format>
#include <string>
#include <vector>

std::vector<std::string> argumentLocations(const std::string& types, bool isMember)
{
    static const char* const ints[]{ "rcx", "rdx", "r8", "r9" };
    static const char* const floats[]{ "xmm0", "xmm1", "xmm2", "xmm3" };
    std::vector<std::string> out;
    std::size_t slot{ isMember ? 1u : 0u };
    for (char t : types)
    {
        if (slot < 4) out.push_back(t == 'f' ? floats[slot] : ints[slot]);
        else out.push_back(std::format("[rsp+{:X}h]", 0x28 + (slot - 4) * 8));
        ++slot;
    }
    return out;
}

unitTests:
using L = std::vector<std::string>;
TEST("mixed types use the slot's register") { CHECK(argumentLocations("ifi", false) == L({ "rcx", "xmm1", "r8" })); }
TEST("this takes the first slot") { CHECK(argumentLocations("ii", true) == L({ "rdx", "r8" })); CHECK(argumentLocations("f", true) == L({ "xmm1" })); }
TEST("the fifth goes on the stack") { CHECK(argumentLocations("iiiiif", false) == L({ "rcx", "rdx", "r8", "r9", "[rsp+28h]", "[rsp+30h]" })); }
TEST("all floats") { CHECK(argumentLocations("ffff", false) == L({ "xmm0", "xmm1", "xmm2", "xmm3" })); }
TEST("a member with four arguments") { CHECK(argumentLocations("iiii", true) == L({ "rdx", "r8", "r9", "[rsp+28h]" })); }
TEST("many arguments") { CHECK_EQ(argumentLocations("iiiiiiiii", false).back(), std::string("[rsp+48h]")); }
TEST("no arguments") { CHECK(argumentLocations("", false).empty()); CHECK(argumentLocations("", true).empty()); }

